class Solution {
    public int widestGap(int[] nums) {
        int[] a = nums.clone();
        Arrays.sort(a);
        int best = 0;
        for (int i = 1; i < a.length; i++) best = Math.max(best, a[i] - a[i - 1]);
        return best;
    }
}

