static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int widestGap(int* nums, int numsSize) {
    int* a = malloc(numsSize * sizeof(int));
    memcpy(a, nums, numsSize * sizeof(int));
    qsort(a, numsSize, sizeof(int), cmp_int);
    int best = 0;
    for (int i = 1; i < numsSize; i++) if (a[i] - a[i - 1] > best) best = a[i] - a[i - 1];
    free(a);
    return best;
}

