class Solution {
    public int widestGap(int[] nums) {
        int n = nums.length, lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
        for (int x : nums) { lo = Math.min(lo, x); hi = Math.max(hi, x); }
        if (n < 2 || lo == hi) return 0;
        int size = Math.max(1, (hi - lo) / (n - 1));
        int count = (hi - lo) / size + 1;
        int[] bmin = new int[count], bmax = new int[count];
        boolean[] used = new boolean[count];
        for (int x : nums) {
            int b = (x - lo) / size;
            if (!used[b]) { used[b] = true; bmin[b] = x; bmax[b] = x; }
            else { bmin[b] = Math.min(bmin[b], x); bmax[b] = Math.max(bmax[b], x); }
        }
        int best = 0, prev = lo;
        for (int b = 0; b < count; b++) if (used[b]) { best = Math.max(best, bmin[b] - prev); prev = bmax[b]; }
        return best;
    }
}

