code.c:
int widestGap(int* nums, int numsSize) {
    int n = numsSize, lo = nums[0], hi = nums[0];
    for (int i = 1; i < n; i++) { if (nums[i] < lo) lo = nums[i]; if (nums[i] > hi) hi = nums[i]; }
    if (n < 2 || lo == hi) return 0;
    int size = (hi - lo) / (n - 1);
    if (size < 1) size = 1;
    int count = (hi - lo) / size + 1;
    int* bmin = malloc(count * sizeof(int));
    int* bmax = malloc(count * sizeof(int));
    for (int b = 0; b < count; b++) { bmin[b] = INT_MAX; bmax[b] = INT_MIN; }
    for (int i = 0; i < n; i++) {
        int b = (nums[i] - lo) / size;
        if (nums[i] < bmin[b]) bmin[b] = nums[i];
        if (nums[i] > bmax[b]) bmax[b] = nums[i];
    }
    int best = 0, prev = lo;
    for (int b = 0; b < count; b++) if (bmin[b] != INT_MAX) { if (bmin[b] - prev > best) best = bmin[b] - prev; prev = bmax[b]; }
    free(bmin); free(bmax);
    return best;
}
